const express=require('express'),router=express.Router(),avatarController=require('../controllers/avatarsController.min.js'),{onlyAdminAuth}=require('../middlewares/auth.min.js'),cache=require('../route_cache.js'),FIVE_HOURS=18e3;router.post('/avatars',onlyAdminAuth,avatarController.create_avatar);router.get('/avatars',cache(FIVE_HOURS),avatarController.get_avatars);router.get('/admin-avatars',onlyAdminAuth,avatarController.get_admin_avatars);router.get('/avatars/:id',onlyAdminAuth,avatarController.get_single_avatar);router.delete('/avatars/:id',onlyAdminAuth,avatarController.delete_avatar);router.put('/avatars/:id',onlyAdminAuth,avatarController.update_avatar);module.exports=router; 